"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["67096"],{43769(e){e.exports=JSON.parse('{"id":"F262","slug":"effective-spread","name":"Effective Spread and Price Impact","subject":"Equity Markets","section":"Equities","topic":"Market microstructure","level":"Intermediate","aliases":["realized spread","market microstructure","trade execution quality","adverse selection"],"formula":{"latex":"ES=2\\\\,D\\\\,(P-M),\\\\quad RS=2\\\\,D\\\\,(P-M_{+5})","also":[],"text":"Effective spread = 2 x D x (Trade price - Mid price before the trade); Realized spread uses the mid price some minutes later; D = +1 for a buy and -1 for a sell"},"symbols":[{"symbol":"D","meaning":"+1 for a buyer-initiated trade, -1 for a seller-initiated trade","unit":"number"},{"symbol":"P","meaning":"Price at which the trade happened","unit":"money"},{"symbol":"M","meaning":"Mid price just before the trade","unit":"money"},{"symbol":"M+5","meaning":"Mid price a few minutes after the trade","unit":"money"}],"when_to_use":"Use it to measure what a trade really cost, since many trades happen inside or outside the quoted spread. The realized spread is what the liquidity provider keeps. The rest is the price impact, the permanent move caused by the information in the trade.","worked_example":{"problem":"A buy order executes at 50.04. The mid price was 50.00 before the trade and 50.03 five minutes later. What are the effective and realized spreads?","inputs":{"p":50.04,"m":50,"m5":50.03,"d":1},"steps":[{"label":"Effective spread = 2 x D x (P - M)","working":"2 x 1 x (50.04-50)","value":"0.0800"},{"label":"Realized spread = 2 x D x (P - M5)","working":"2 x 1 x (50.04-50.03)","value":"0.0200"},{"label":"Price impact = effective - realized","working":"0.08-0.02","value":"0.0600"}],"answer":"The effective spread is 0.0800. The realized spread is 0.0200, so the liquidity provider kept little, and 0.0600 of the cost was price impact, the market moving against the provider."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Trade price","unit":"money","type":"number","default":50.04,"hint":""},{"id":"m","label":"Mid price before the trade","unit":"money","type":"number","default":50,"hint":""},{"id":"m5","label":"Mid price a few minutes later","unit":"money","type":"number","default":50.03,"hint":""},{"id":"d","label":"Trade direction (+1 buy, -1 sell)","unit":"number","type":"number","default":1,"hint":""}],"checks":[{"expr":"d==1 or d==-1","message":"Enter 1 for a buy or -1 for a sell."}],"steps":[{"id":"es","label":"Effective spread = 2 x D x (P - M)","expr":"2*d*(p-m)","format":"num4"},{"id":"rs","label":"Realized spread = 2 x D x (P - M5)","expr":"2*d*(p-m5)","format":"num4"},{"id":"impact","label":"Price impact = effective - realized","expr":"es-rs","format":"num4"}],"results":["es","rs","impact"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"es":0.08,"rs":0.02,"impact":0.06}},"finder":{"finds":"The true cost of a trade and who kept it","needs":"Trade price, mid prices before and after, direction"},"related":[{"slug":"bid-ask-spread","name":"Bid-Ask Spread and Trading Cost"},{"slug":"price-improvement","name":"Price Improvement (Order Flow)"}],"related_ids":["F261","F281"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>E</mi><mi>S</mi><mo>=</mo><mn>2</mn><mtext>\u2009</mtext><mi>D</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mi>P</mi><mo>\u2212</mo><mi>M</mi><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>R</mi><mi>S</mi><mo>=</mo><mn>2</mn><mtext>\u2009</mtext><mi>D</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mi>P</mi><mo>\u2212</mo><msub><mi>M</mi><mrow><mo>+</mo><mn>5</mn></mrow></msub><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">ES=2\\\\,D\\\\,(P-M),\\\\quad RS=2\\\\,D\\\\,(P-M_{+5})</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>E</mi><mi>S</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle ES</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mn>2</mn><mtext>\u2009</mtext><mi>D</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mi>P</mi><mo>\u2212</mo><mi>M</mi><mo stretchy=\\"false\\">)</mo></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =2\\\\,D\\\\,(P-M)</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>R</mi><mi>S</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle RS</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mn>2</mn><mtext>\u2009</mtext><mi>D</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mi>P</mi><mo>\u2212</mo><msub><mi>M</mi><mrow><mo>+</mo><mn>5</mn></mrow></msub><mo stretchy=\\"false\\">)</mo></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =2\\\\,D\\\\,(P-M_{+5})</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"effective-duration-convexity","name":"Effective Duration and Convexity"},"next":{"slug":"efficiency-turnover-ratios","name":"Efficiency Ratios: Asset, Inventory, Receivable and Payable Turnover"},"lesson":null,"total":522}')}}]);